select ssd.sku_no as skuNo, sum(ssd.scrap_qty) as qty from sample_scrap_detail ssd inner join sample_scrap_info ssi on ssd.main_id = ssi. id and ssi.is_deleted = false where ssd.is_deleted = false and ssi.approve_status != 'approve'
and ssd.sku_no in
#{item}
and ssd.main_id != #{id}
GROUP BY ssd.sku_no
